    if(/\.txt$/i.test(f.name) || /^text\//.test(f.type)){ const t = await f.text(); T.value = (T.value ? T.value + '\n' : '') + t.slice(0, 5000); kToast('Der Text steht jetzt im Feld.'); return; }
