    const f = new File([blob], `${heute}_${sgSlug(v.titel || 'Plakat')}_${v.format}_v01.png`, { type:'image/png' });
    if(x === 'teilen' && navigator.canShare && navigator.canShare({ files:[f] })){ try{ await navigator.share({ files:[f], text:(v.texte && v.texte.whatsapp) || '' }); return; }catch(e){ if(e && e.name === 'AbortError') return; } }
